import {initial,forward,backward,entries,get,update,numericalGradient,linear,linearStep,data} from './ai-neural-model.js';
const $=id=>document.getElementById(id),fmt=v=>Number(v).toFixed(4);
const lessons={
 neuron:{title:'Neuron · รับค่า คูณ แล้วรวม',intro:'Neuron ในโมเดลนี้รับตัวเลข 2 ค่า คูณด้วยน้ำหนักแต่ละเส้น แล้วบวก Bias ก่อนส่งไป Activation บทนี้แยกดูผลรวม z ก่อน ยังไม่ใช่สมองหรือการตัดสินใจแบบมนุษย์',terms:[['Input','ตัวเลขที่ส่งเข้ามา เช่น x₁ และ x₂'],['Weight (w)','ตัวคูณที่กำหนดอิทธิพลและทิศทางของ Input'],['Bias (b)','ค่าที่บวกเพิ่ม แม้ Input เป็นศูนย์'],['z / Weighted sum','ผลรวม x₁w₁ + x₂w₂ + b ยังไม่ผ่าน Activation']],task:'ตั้ง x₁=1, x₂=0.5, w₂=−0.4, b=0.1 เปลี่ยน w₁ จาก 0.8 เป็น 1.3 สังเกต z จาก 0.7 เป็น 1.2 แล้วกดตรวจภารกิจ',steps:['คูณ Input ด้วย Weight','รวมผลคูณ และบวก Bias']},
 forward:{title:'Forward Pass · คำนวณทีละชั้น',intro:'ให้ Input เดินผ่านโครงข่าย 2 → 3 → 2 เราคำนวณ z ของชั้นซ่อน ผ่าน tanh แล้วใช้ค่าที่ได้คำนวณเอาต์พุต 2 ค่า น้ำหนักยังไม่เปลี่ยนเพียงเพราะกดเล่น',terms:[['Hidden layer','ชั้นคำนวณระหว่าง Input กับ Output'],['tanh / Activation','ฟังก์ชันไม่เชิงเส้น เปลี่ยน z เป็นค่าระหว่าง −1 กับ 1'],['Output (ŷ)','ค่าตัวเลขที่โมเดลทำนาย ไม่ใช่ความน่าจะเป็น'],['Forward pass','คำนวณจาก Input ไป Output ด้วยพารามิเตอร์ปัจจุบัน']],task:'เปลี่ยน x₁ จาก 1 เป็น 0 แล้วเล่นจนถึงเอาต์พุต สังเกตว่าค่า Hidden และ Output เปลี่ยน แต่น้ำหนัก w ไม่เปลี่ยน ตารางแสดงผลจากโมเดลเดียวกับภาพ',steps:['Input → ผลรวม z','z → tanh → Hidden','Hidden → Output']},
 gradient:{title:'Gradient Descent · ลดความคลาดเคลื่อน',intro:'เริ่มจากเส้นตรง ŷ = wx + b ที่ทายจุดข้อมูล 6 จุดไม่ดี ผิว 3D คือ Loss ที่คำนวณจริงสำหรับคู่ w,b ต่าง ๆ ความสูงบอกความผิดพลาด กดอัปเดตเพื่อก้าวสวน Gradient',terms:[['Target','คำตอบตัวอย่างที่ใช้เปรียบเทียบ ไม่ใช่สิ่งที่โมเดลทายเอง'],['Loss / MSE','ค่าเฉลี่ยของ (ค่าทำนาย − Target)²'],['Gradient','ความไวของ Loss ต่อการเปลี่ยนพารามิเตอร์'],['Learning rate (η)','ขนาดก้าวฝึก ไม่ใช่ความเร็ว animation']],task:'ใช้ Learning rate 0.15 กดฝึก 10 ก้าว ดู Loss เทียบค่าตั้งต้น แล้วทดลองเริ่มใหม่และใช้ 2.0 อย่างน้อย 2 ก้าว สังเกตว่าก้าวใหญ่ไม่ได้รับประกันว่าจะดีขึ้น ภารกิจตรวจเมื่อทดลองครบทั้งสองขนาดก้าว',steps:['ข้อมูล 6 จุด → Loss','คำนวณ Gradient','w,b ใหม่ = ค่าเดิม − η × Gradient']},
 backprop:{title:'Backpropagation · ย้อนหาความไว',intro:'หลัง Forward เรารู้ Loss แต่ยังไม่รู้ควรเปลี่ยนน้ำหนักใดเท่าไร Backpropagation ใช้ Chain rule ย้อนหาอนุพันธ์ ไม่ได้ส่งคำตอบหรือ Packet ย้อนกลับ และยังไม่เปลี่ยนพารามิเตอร์จนกดฝึก',terms:[['Derivative / อนุพันธ์','การเปลี่ยนเล็กน้อยของค่า เปรียบเทียบกับสิ่งที่เปลี่ยน'],['Chain rule','รวมความไวตามลำดับฟังก์ชันที่ต่อกัน'],['∂L/∂w','Gradient ของ Loss ต่อ Weight หนึ่งค่า'],['Finite difference','ลองเพิ่ม/ลด Weight นิดหนึ่งเพื่อเทียบ Gradient คำนวณ']],task:'เล่นจาก Input จนถึง Gradient ตรวจตารางว่าค่าอนุพันธ์ของ w₁[1,1] ตรงกับ Finite difference จากนั้นกด “ฝึก 1 ก้าว” ดู Loss ก่อน–หลัง การกดเล่นอย่างเดียวไม่ถือว่าฝึก',steps:['Input → Hidden','Hidden ผ่าน tanh','Hidden → Output / Loss','Loss → Gradient ของ Output','ย้อนผ่าน tanh → Hidden gradient','Gradient ของ Weight / Bias']}
};
let state,scene,generation=0;const completed=new Set();
function fresh(id){return {lesson:id,p:initial(),x:[1,.5],weights:[.8,-.4],bias:.1,rate:.15,step:0,playing:false,speed:Number($('speed').value),revision:++generation,history:[{w:-1.2,b:-.8}],trained:0,compared:false};}
function calculate(){state.f=backward(state.p,state.x);state.z=state.x.reduce((s,x,i)=>s+x*state.weights[i],state.bias);}
const row=(a,b)=>`<tr><td>${a}</td><td>${b}</td></tr>`;
function render(){calculate();const l=lessons[state.lesson];$('scene-title').textContent=l.steps[state.step];$('step').textContent=`${state.step+1}/${l.steps.length} · ${l.steps[state.step]}`;$('play').textContent=state.playing?'Ⅱ หยุด':'▶ เล่น';$('previous').disabled=state.step===0;$('next').disabled=state.step===l.steps.length-1;if(state.lesson==='backprop'&&state.step===5)state.reviewed=true;
 if(state.lesson==='neuron')$('result').innerHTML=`<p class="metric">z = ${fmt(state.z)}</p><p class="explain">${state.x.map((x,i)=>`(${x} × ${state.weights[i]})`).join(' + ')} + ${state.bias} = ${fmt(state.z)}</p>`;
 else if(state.lesson==='gradient'){const end=state.history.at(-1),f=linear(end.w,end.b);$('result').innerHTML=`<p class="metric">Loss ${fmt(f.loss)} · ${state.history.length-1} ก้าว</p><p>∂L/∂w ${fmt(f.dw)} · ∂L/∂b ${fmt(f.db)} · η ${state.rate}</p><table><thead><tr><th>ก้าว</th><th>Loss</th></tr></thead><tbody>${state.history.map((p,i)=>row(i,fmt(linear(p.w,p.b).loss))).join('')}</tbody></table><p class="explain">ความสูงผิวย่อไว้ไม่เกิน 8 เพื่อให้อ่านภาพได้ ตารางคง Loss จริง แม้จุดออกนอกช่วงผิว ไม่บีบค่าฝึกให้ดูสำเร็จ</p>`;}
 else {const f=state.f;$('result').innerHTML=`<p class="metric">ŷ = [${f.y.map(fmt).join(', ')}] · Loss ${fmt(f.loss)}</p><p>Target = [1, −0.5] · MSE = ((ŷ₁−1)² + (ŷ₂+0.5)²) ÷ 2</p><table><thead><tr><th>ค่า / พารามิเตอร์</th><th>${state.lesson==='backprop'?'Gradient ∂L/∂parameter':'ค่าปัจจุบัน'}</th></tr></thead><tbody>${state.lesson==='backprop'&&state.step>=3?entries(state.p).map(e=>row(e.name,fmt(get(f.grad,e)))).join(''):f.z.map((v,i)=>row(`z${i+1} → tanh → h${i+1}`,`${fmt(v)} → ${fmt(f.h[i])}`)).join('')+entries(state.p).map(e=>row(e.name,fmt(e.value))).join('')}</tbody></table>${state.lesson==='backprop'?`<p>Gradient w₁[1,1]: ${fmt(f.grad.w1[0][0])} · Finite difference: ${fmt(numericalGradient(state.p,state.x,[1,-.5],entries(state.p)[0]))}</p><p>${state.compared?'ผ่านการฝึกแล้ว · '+state.lastChange:'ยังไม่ได้อัปเดตน้ำหนัก การเล่นเป็นการดู trace เท่านั้น'}</p>`:''}`;}
 if(state.lesson==='gradient'){
   const p=state.history.at(-1),details=document.createElement('details');details.innerHTML=`<summary>ดูข้อมูล 6 จุดและค่าทำนายจริง</summary><table><thead><tr><th>x</th><th>Target</th><th>ŷ = wx+b</th></tr></thead><tbody>${data.map(([x,y])=>`<tr><td>${x}</td><td>${y}</td><td>${fmt(p.w*x+p.b)}</td></tr>`).join('')}</tbody></table>`;$('result').append(details);
 }else if(state.lesson==='backprop'&&state.step<3){$('result').querySelector('th:last-child').textContent='ค่าปัจจุบัน (ยังไม่แสดง Gradient)';}
}
function advance(){if(state.step<lessons[state.lesson].steps.length-1)state.step++;else {state.playing=false;completed.add(state.lesson);}render();}
function input(label,value,onchange,min=-2,max=2){const el=document.createElement('label');el.textContent=label;const field=document.createElement('input');field.type='number';field.step='.01';field.min=min;field.max=max;field.value=value;el.append(field);field.addEventListener('input',()=>{const v=Number(field.value);if(!Number.isFinite(v)||v<min||v>max||field.value.trim()===''){field.setAttribute('aria-invalid','true');$('feedback').textContent=`กรอกค่าระหว่าง ${min} และ ${max} · ยังใช้ค่าที่ถูกต้องล่าสุด`;return;}field.removeAttribute('aria-invalid');onchange(v);state.step=0;state.playing=false;state.revision++;$('feedback').textContent='ค่าคำนวณเปลี่ยนแล้ว เล่นเพื่อดูขั้นตอนใหม่';render();});$('inputs').append(el);}
function training(){try{if(state.lesson==='gradient'){const p=state.history.at(-1),q=linearStep(p.w,p.b,state.rate);if(!Number.isFinite(q.w)||Math.abs(q.w)>1e6||Math.abs(q.b)>1e6)throw Error('ค่าฝึกสูงเกินช่วงต้นแบบ ลด Learning rate แล้วเริ่มใหม่');state.history.push({w:q.w,b:q.b});if(state.rate===.15&&state.history.length>=11)completed.add('small-rate');if(state.rate===2&&state.history.length>=3)completed.add('large-rate');state.step=2;}else {const before=state.f.loss;state.p=update(state.p,state.f.grad,state.rate);state.compared=true;state.lastChange=`Loss ${fmt(before)} → ${fmt(forward(state.p,state.x).loss)}`;state.step=0;}state.trained++;state.revision++;state.playing=true;render();}catch(e){$('feedback').textContent=e.message;state.playing=false;render();}}
function open(id){state=fresh(id);calculate();const l=lessons[id];$('title').textContent=l.title;$('intro').textContent=l.intro;$('task').textContent=l.task;$('scene-title').textContent=l.steps[0];$('terms').innerHTML=l.terms.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('');$('feedback').textContent='';$('inputs').replaceChildren();document.querySelectorAll('[data-lesson]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.lesson===id)));
 if(id!=='gradient'){input('Input x₁',1,v=>state.x[0]=v);input('Input x₂',.5,v=>state.x[1]=v);}if(id==='neuron'){input('Weight w₁',.8,v=>state.weights[0]=v);input('Weight w₂',-.4,v=>state.weights[1]=v);input('Bias b',.1,v=>state.bias=v);}if(id==='gradient'||id==='backprop'){input('Learning rate η',.15,v=>state.rate=v,.01,2);const b=document.createElement('button');b.textContent=id==='gradient'?'ฝึก 1 ก้าว (w,b)':'ฝึก 1 ก้าว (17 พารามิเตอร์)';b.id='train';b.addEventListener('click',training);$('inputs').append(b);}render();}
document.querySelectorAll('[data-lesson]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.lesson)));
$('previous').onclick=()=>{state.playing=false;state.step=Math.max(0,state.step-1);render();};$('next').onclick=()=>{state.playing=false;advance();};$('play').onclick=()=>{if(state.step===lessons[state.lesson].steps.length-1&&!state.playing)state.step=0;state.playing=!state.playing;render();};$('speed').onchange=()=>state.speed=Number($('speed').value);$('reset').onclick=()=>open(state.lesson);$('view').onclick=()=>scene?.resetView();
$('check').onclick=()=>{let ok=false;if(state.lesson==='neuron')ok=state.x[0]===1&&state.x[1]===.5&&state.weights[0]===1.3&&state.weights[1]===-.4&&state.bias===.1;else if(state.lesson==='forward')ok=state.x[0]===0&&state.step===2;else if(state.lesson==='gradient')ok=completed.has('small-rate')&&completed.has('large-rate');else ok=state.reviewed&&state.compared&&Math.abs(state.f.grad.w1[0][0]-numericalGradient(state.p,state.x,[1,-.5],entries(state.p)[0]))<1e-7;$('feedback').textContent=ok?'✓ ทำภารกิจครบตามค่าคำนวณแล้ว ลองอธิบายว่าอะไรเปลี่ยน และเพราะอะไร':'ยังไม่ครบ ลองทำตามค่าหรือจำนวนก้าวที่ระบุในภารกิจ';};
const backLink=document.createElement('a');backLink.href='ai-foundations.html';backLink.textContent='← บทปูพื้น: ข้อมูล / Vector / Activation / Loss';backLink.style.display='block';backLink.style.margin='16px 0';document.querySelector('nav').after(backLink);
const requested=location.hash.slice(1);open(Object.hasOwn(lessons,requested)?requested:'neuron');try {const {mountScene}=await import('./ai-neural-scene.js');scene=mountScene($('stage'),()=>state,advance);}catch(e){$('fallback').hidden=false;$('feedback').textContent='3D ไม่พร้อม แต่การคำนวณและปุ่มเดินขั้นยังใช้ได้';$('play').disabled=true;}window.addEventListener('pagehide',()=>scene?.dispose());
